insert into public.site_settings(key,value,is_public)
values
  ('auth_copy_ar', to_jsonb(E'loginEyebrow || تسجيل الدخول\nregisterEyebrow || ACCOUNT\nloginTitle || تسجيل الدخول\nregisterTitle || أنشئ حسابك في ezyjobs\nloginLead || ادخل إلى حسابك لمتابعة ملفك المهني وتقديماتك والفرص التي حفظتها.\nregisterLead || حساب واحد يجمع ملفك المهني، الوظائف المحفوظة، وتقديماتك في مكان واحد.\nloginCardTitle || تسجيل الدخول\nregisterCardTitle || حساب جديد\nidentifierLabel || البريد الإلكتروني أو اسم المستخدم\nidentifierHint || يمكنك التسجيل ببريدك الإلكتروني أو استخدام اسم مستخدم قديم متوافق مع النظام.\npasswordLabel || كلمة المرور\nconfirmPasswordLabel || تأكيد كلمة المرور\nsubmitLogin || دخول\nsubmitRegister || إنشاء الحساب\nprocessing || جارٍ المعالجة\npasswordMismatch || كلمتا المرور غير متطابقتين.\nexistingAccount || لديك حساب؟\nnoAccount || ليس لديك حساب؟\nloginLink || تسجيل الدخول\nregisterLink || إنشاء حساب\nbenefit1 || حفظ الوظائف المناسبة ومتابعتها\nbenefit2 || بناء ملف مهني منظم\nbenefit3 || تنظيم التقديمات ومراحلها\nbenefit4 || إنشاء تنبيهات للفرص الجديدة'::text), true),
  ('alerts_copy_ar', to_jsonb(E'eyebrow || تنبيهات\ntitle || الوظائف الجديدة تصلك، وأنت غائب عنها\nlead || الوظائف عن بُعد عمرها يوم أو يومان. من يتصفح يومياً يرى القليل. من يصله تنبيه يرى كل شيء.\nemailLabel || بريدك الإلكتروني\nemailHint || نستخدمه لإرسال التنبيهات فقط. لا نشاركه مع أي جهة.\ncountryLabel || دولتك\nlanguageLabel || اللغة المطلوبة في الوظيفة\nanyLanguage || أي لغة\ncategoriesLabel || المجالات التي تهمّك\ncategoriesHint || اتركها فارغة لتصلك كل المجالات.\nremoteLabel || عن بُعد فقط\nremoteHint || يُستبعد ما يتطلب حضوراً\nnoExperienceLabel || بدون خبرة فقط\nnoExperienceHint || لا تشترط سنوات سابقة\nstudentsLabel || مناسبة للطلاب\nstudentsHint || دوام جزئي أو تدريب\nfrequencyLabel || التكرار\ndaily || يومياً\nweekly || أسبوعياً\nsubmit || فعّل التنبيه\nbusy || جارٍ التسجيل\npreviewNoticeTitle || وضع المعاينة\npreviewNotice || لن يُرسل بريد فعلياً قبل ربط Supabase. حالياً يُحفظ التنبيه في متصفحك فقط.\nwhatYouGet || ما الذي يصلك فعلاً؟\nprivacyTitle || لماذا لا نبيع بريدك؟'::text), true),
  ('applications_copy_ar', to_jsonb(E'eyebrow || Application Center\ntitle || مسار كل تقديماتك\nlead || من الحفظ والتحضير إلى التقديم والمقابلة والعرض، بدون جدول خارجي.\nopenJobs || اكتشف وظائف\ncurrentTitle || الطلبات الحالية\nallStatuses || كل الحالات\nemptyTitle || لا توجد طلبات هنا\nemptyBody || من أي صفحة وظيفة، أضفها لمسار التقديم ثم حدّث حالتها مع تقدّمك.\nstartSearch || ابدأ البحث\njobPage || صفحة الوظيفة\nprepare || جهّز التقديم\nopenApplication || فتح التقديم\nremove || إزالة\nstatusLabel || الحالة\nnotesLabel || ملاحظاتك\nnotesPlaceholder || مثلاً: CV v2، مقابلة الثلاثاء، متابعة بعد 5 أيام.\ntrackSaved || {count} وظيفة في المسار\ntrackEmpty || لم تضف أي وظيفة بعد.\nappliedOn || تم التقديم'::text), true),
  ('profile_copy_ar', to_jsonb(E'eyebrow || Career Passport\ntitle || ملفك المهني يبدأ من CV واحد\nlead || ارفع PDF، راجع النتائج قبل اعتمادها، ثم استخدمها مباشرة في مطابقة الوظائف.\ncvTitle || تحليل السيرة الذاتية\ncvLead || التحليل يتم محلياً في المتصفح. لا نرسل ملف PDF إلى خدمة ذكاء اصطناعي خارجية.\nupload || رفع CV بصيغة PDF\nanalyzing || جارٍ التحليل\nnoCvTitle || لم ترفع CV بعد\nnoCvLead || يمكنك أيضاً تعبئة الملف يدوياً أسفل الصفحة.\naccountSettings || إعدادات الحساب\naccountLead || غيّر كلمة المرور من هنا في أي وقت.\nnewPassword || كلمة المرور الجديدة\nconfirmPassword || تأكيد كلمة المرور\nchangePassword || تغيير كلمة المرور\nshowOpportunities || شاهد فرصك\nmyApplications || تقديماتي\nlatestCv || آخر CV معتمد\ncvRefresh || يمكنك رفع نسخة أحدث في أي وقت.\nskillsFound || المهارات المكتشفة\neducationFound || التعليم الذي التقطناه\nexperienceFound || الخبرة التي التقطناها'::text), true)
insert into public.site_settings(key,value,is_public)
values
  ('auth_copy_en', to_jsonb(E'loginEyebrow || SIGN IN\nregisterEyebrow || ACCOUNT\nloginTitle || Sign in to ezyjobs\nregisterTitle || Create your ezyjobs account\nloginLead || Sign in to follow your professional profile, applications and saved opportunities.\nregisterLead || One account for your profile, saved jobs and application tracking.\nloginCardTitle || Sign in\nregisterCardTitle || New account\nidentifierLabel || Email or username\nidentifierHint || You can use your email address or an older compatible username.\npasswordLabel || Password\nconfirmPasswordLabel || Confirm password\nsubmitLogin || Sign in\nsubmitRegister || Create account\nprocessing || Processing\npasswordMismatch || Passwords do not match.\nexistingAccount || Already have an account?\nnoAccount || Do not have an account?\nloginLink || Sign in\nregisterLink || Create account\nbenefit1 || Save and follow useful jobs\nbenefit2 || Build an organized professional profile\nbenefit3 || Track applications and stages\nbenefit4 || Create alerts for new opportunities'::text), true),
  ('alerts_copy_en', to_jsonb(E'eyebrow || Job alerts\ntitle || New jobs reach you while you are away\nlead || Remote jobs can be short-lived. A daily browser sees a few; an alert keeps you informed.\nemailLabel || Your email\nemailHint || We use it only for alerts and do not share it with other parties.\ncountryLabel || Your country\nlanguageLabel || Required job language\nanyLanguage || Any language\ncategoriesLabel || Fields you care about\ncategoriesHint || Leave empty to receive all fields.\nremoteLabel || Remote only\nremoteHint || Excludes roles requiring presence\nnoExperienceLabel || No experience only\nnoExperienceHint || No prior years required\nstudentsLabel || Student friendly\nstudentsHint || Part-time or training\nfrequencyLabel || Frequency\ndaily || Daily\nweekly || Weekly\nsubmit || Activate alert\nbusy || Saving\npreviewNoticeTitle || Preview mode\npreviewNotice || Email delivery requires Supabase. For now the alert is stored in your browser.\nwhatYouGet || What you receive\nprivacyTitle || Why we do not sell your email'::text), true),
  ('applications_copy_en', to_jsonb(E'eyebrow || Application Center\ntitle || Your application pipeline\nlead || From saving and preparation to applying, interviews and offers, without an external spreadsheet.\nopenJobs || Discover jobs\ncurrentTitle || Current applications\nallStatuses || All statuses\nemptyTitle || Nothing here yet\nemptyBody || From any job page, add a role to your application track and update it as you progress.\nstartSearch || Start searching\njobPage || Job page\nprepare || Prepare application\nopenApplication || Open application\nremove || Remove\nstatusLabel || Status\nnotesLabel || Your notes\nnotesPlaceholder || Example: CV v2, Tuesday interview, follow up in 5 days.\ntrackSaved || {count} jobs in the track\ntrackEmpty || No jobs added yet.\nappliedOn || Applied'::text), true),
  ('profile_copy_en', to_jsonb(E'eyebrow || Career Passport\ntitle || Your professional profile starts with one CV\nlead || Upload a PDF, review what was extracted, then use it for job matching.\ncvTitle || CV analysis\ncvLead || Analysis runs locally in your browser. We do not send your PDF to an external AI service.\nupload || Upload PDF CV\nanalyzing || Analyzing\nnoCvTitle || No CV uploaded yet\nnoCvLead || You can also complete your profile manually below.\naccountSettings || Account settings\naccountLead || Change your password here at any time.\nnewPassword || New password\nconfirmPassword || Confirm password\nchangePassword || Change password\nshowOpportunities || View your opportunities\nmyApplications || My applications\nlatestCv || Latest approved CV\ncvRefresh || You can upload a newer version at any time.\nskillsFound || Detected skills\neducationFound || Education detected\nexperienceFound || Experience detected'::text), true)
insert into public.site_settings(key,value,is_public)
values
  ('auth_copy_fr', to_jsonb(E'loginEyebrow || CONNEXION\nregisterEyebrow || COMPTE\nloginTitle || Connexion à ezyjobs\nregisterTitle || Créer votre compte ezyjobs\nloginLead || Connectez-vous pour suivre votre profil, vos candidatures et vos opportunités enregistrées.\nregisterLead || Un compte pour votre profil, vos offres enregistrées et le suivi de vos candidatures.\nloginCardTitle || Connexion\nregisterCardTitle || Nouveau compte\nidentifierLabel || E-mail ou nom d’utilisateur\nidentifierHint || Vous pouvez utiliser votre e-mail ou un ancien nom d’utilisateur compatible.\npasswordLabel || Mot de passe\nconfirmPasswordLabel || Confirmer le mot de passe\nsubmitLogin || Se connecter\nsubmitRegister || Créer le compte\nprocessing || Traitement\npasswordMismatch || Les mots de passe ne correspondent pas.\nexistingAccount || Vous avez déjà un compte ?\nnoAccount || Vous n’avez pas de compte ?\nloginLink || Se connecter\nregisterLink || Créer un compte\nbenefit1 || Enregistrer et suivre les offres utiles\nbenefit2 || Construire un profil professionnel organisé\nbenefit3 || Suivre les candidatures et leurs étapes\nbenefit4 || Créer des alertes pour les nouvelles opportunités'::text), true),
  ('alerts_copy_fr', to_jsonb(E'eyebrow || Alertes emploi\ntitle || Recevez les nouvelles offres même quand vous êtes absent\nlead || Les offres à distance peuvent être éphémères. Une alerte vous permet de rester informé.\nemailLabel || Votre e-mail\nemailHint || Nous l’utilisons uniquement pour les alertes et ne le partageons pas.\ncountryLabel || Votre pays\nlanguageLabel || Langue requise\nanyLanguage || Toutes les langues\ncategoriesLabel || Domaines qui vous intéressent\ncategoriesHint || Laissez vide pour recevoir tous les domaines.\nremoteLabel || À distance uniquement\nremoteHint || Exclut les postes nécessitant une présence\nnoExperienceLabel || Sans expérience uniquement\nnoExperienceHint || Sans années d’expérience requises\nstudentsLabel || Adapté aux étudiants\nstudentsHint || Temps partiel ou formation\nfrequencyLabel || Fréquence\ndaily || Quotidien\nweekly || Hebdomadaire\nsubmit || Activer l’alerte\nbusy || Enregistrement\npreviewNoticeTitle || Mode aperçu\npreviewNotice || L’envoi d’e-mails nécessite Supabase. Pour le moment, l’alerte est conservée dans votre navigateur.\nwhatYouGet || Ce que vous recevez\nprivacyTitle || Pourquoi nous ne vendons pas votre e-mail'::text), true),
  ('applications_copy_fr', to_jsonb(E'eyebrow || Centre de candidatures\ntitle || Votre parcours de candidatures\nlead || De l’enregistrement à la préparation, la candidature, les entretiens et les offres, sans tableau externe.\nopenJobs || Découvrir les offres\ncurrentTitle || Candidatures actuelles\nallStatuses || Tous les statuts\nemptyTitle || Rien ici pour le moment\nemptyBody || Depuis une page d’offre, ajoutez un poste à votre parcours puis mettez son statut à jour.\nstartSearch || Commencer la recherche\njobPage || Page du poste\nprepare || Préparer la candidature\nopenApplication || Ouvrir la candidature\nremove || Supprimer\nstatusLabel || Statut\nnotesLabel || Vos notes\nnotesPlaceholder || Exemple : CV v2, entretien mardi, relance dans 5 jours.\ntrackSaved || {count} offres dans le parcours\ntrackEmpty || Aucune offre ajoutée.\nappliedOn || Candidature envoyée le'::text), true),
  ('profile_copy_fr', to_jsonb(E'eyebrow || Career Passport\ntitle || Votre profil professionnel commence par un CV\nlead || Importez un PDF, vérifiez les résultats, puis utilisez-les pour les correspondances d’emploi.\ncvTitle || Analyse du CV\ncvLead || L’analyse s’effectue localement dans votre navigateur. Nous n’envoyons pas votre PDF à un service IA externe.\nupload || Importer un CV PDF\nanalyzing || Analyse en cours\nnoCvTitle || Aucun CV importé\nnoCvLead || Vous pouvez aussi compléter le profil manuellement ci-dessous.\naccountSettings || Paramètres du compte\naccountLead || Changez votre mot de passe ici à tout moment.\nnewPassword || Nouveau mot de passe\nconfirmPassword || Confirmer le mot de passe\nchangePassword || Changer le mot de passe\nshowOpportunities || Voir vos opportunités\nmyApplications || Mes candidatures\nlatestCv || Dernier CV validé\ncvRefresh || Vous pouvez importer une version plus récente à tout moment.\nskillsFound || Compétences détectées\neducationFound || Formation détectée\nexperienceFound || Expérience détectée'::text), true)
